def _normalize_ciphers(ciphers):
    if ciphers is None:
        return None
    if isinstance(ciphers, string_types):
        value = ciphers
    elif isinstance(ciphers, (list, tuple)) and ciphers and all(isinstance(cipher, string_types) and cipher for cipher in ciphers):
        value = ':'.join(ciphers)
    else:
        raise ValueError('Invalid ciphers value: provide an OpenSSL cipher string or a non-empty list of cipher strings')
    if not value:
        raise ValueError('Invalid ciphers value: provide an OpenSSL cipher string or a non-empty list of cipher strings')
    return value


def make_context(cafile=None, cadata=None, ciphers=None, validate_certs=True):
    """Create an SSL context with optional trust roots and cipher configuration."""
    ciphers = _normalize_ciphers(ciphers)
    if HAS_SSLCONTEXT:
        if validate_certs:
            context = create_default_context(cafile=cafile)
        else:
            context = SSLContext(ssl.PROTOCOL_SSLv23)
            if getattr(ssl, 'OP_NO_SSLv2', 0):
                context.options |= ssl.OP_NO_SSLv2
            if getattr(ssl, 'OP_NO_SSLv3', 0):
                context.options |= ssl.OP_NO_SSLv3
            context.verify_mode = ssl.CERT_NONE
            context.check_hostname = False
    elif HAS_URLLIB3_PYOPENSSLCONTEXT:
        context = PyOpenSSLContext(PROTOCOL)
    else:
        raise NotImplementedError('Host libraries are too old to support creating an sslcontext')

    if validate_certs and (cafile or cadata):
        context.load_verify_locations(cafile=cafile, cadata=cadata)
    if ciphers is not None:
        try:
            if hasattr(context, 'set_ciphers'):
                context.set_ciphers(ciphers)
            else:
                context.set_cipher_list(to_bytes(ciphers))
        except Exception:
            raise ValueError('Invalid or unsupported ciphers value')
    return context
